/**
 * Aligns word-level STT timestamps to a known-accurate list of paragraphs/verses.
 *
 * @param {{ text: string, chunks: { text: string, timestamp: [number, number] }[] }} transcript
 * @param {{text: string, verseNumber: number | undefined}[]} paragraphs - accurate source text, one entry per paragraph/verse
 * @returns {{ text: string, start: number, end: number, boundaries: number[] }[]}
 */
export function alignTranscriptToParagraphs(transcript, paragraphs) {
  // ---- 1. Normalize a word for comparison purposes only (never for output) ----
  const normalize = (w) => w.toLowerCase().replace(/[^a-z0-9']/g, '');

  const tokenize = (str) => (str.match(/[A-Za-z0-9']+/g) || []);

  // ---- 2. Flatten paragraphs into a single word list, tracking which paragraph each word belongs to ----
  // paraWords[i] = { raw, norm, paragraphIndex, indexInParagraph }
  const paraWords = [];
  paragraphs.forEach((p, pIdx) => {
    tokenize(p.text).forEach((w, wIdx) => {
      paraWords.push({ raw: w, norm: normalize(w), paragraphIndex: pIdx, indexInParagraph: wIdx, verseNumber: p.verseNumber });
    });
  });

  // ---- 3. Flatten STT chunks into a comparable word list ----
  const sttWords = transcript.chunks.map((c) => ({
    norm: normalize(c.text),
    start: c.timestamp[0],
    end: c.timestamp[1],
  }));

  const n = paraWords.length; // rows: "accurate" paragraph words
  const m = sttWords.length;  // cols: STT words

  // ---- 4. Needleman-Wunsch global alignment (DP over normalized words) ----
  const MATCH = 2;
  const MISMATCH = -1;
  const GAP = -2;

  // score[i][j] stored as flat Int32Array for memory efficiency
  const score = new Int32Array((n + 1) * (m + 1));
  // traceback: 0 = diag (match/sub), 1 = up (paragraph word unmatched / gap in STT), 2 = left (extra STT word / gap in paragraph)
  const trace = new Uint8Array((n + 1) * (m + 1));

  const idx = (i, j) => i * (m + 1) + j;

  for (let i = 0; i <= n; i++) score[idx(i, 0)] = i * GAP;
  for (let j = 0; j <= m; j++) score[idx(0, j)] = j * GAP;

  for (let i = 1; i <= n; i++) {
    const pWord = paraWords[i - 1].norm;
    for (let j = 1; j <= m; j++) {
      const sWord = sttWords[j - 1].norm;
      const diag = score[idx(i - 1, j - 1)] + (pWord === sWord ? MATCH : MISMATCH);
      const up = score[idx(i - 1, j)] + GAP;   // paragraph word aligned to nothing
      const left = score[idx(i, j - 1)] + GAP; // STT word aligned to nothing

      let best = diag, dir = 0;
      if (up > best) { best = up; dir = 1; }
      if (left > best) { best = left; dir = 2; }

      score[idx(i, j)] = best;
      trace[idx(i, j)] = dir;
    }
  }

  // ---- 5. Traceback: build matchedTimestamp[paragraphWordIndex] = { start, end } | null ----
  const matched = new Array(n).fill(null);
  let i = n, j = m;
  while (i > 0 || j > 0) {
    const dir = i > 0 && j > 0 ? trace[idx(i, j)] : (i > 0 ? 1 : 2);
    if (dir === 0) {
      matched[i - 1] = { start: sttWords[j - 1].start, end: sttWords[j - 1].end };
      i--; j--;
    } else if (dir === 1) {
      matched[i - 1] = null; // paragraph word not found in STT output
      i--;
    } else {
      j--; // extra STT word (filler, repetition, mis-segmentation) — ignored
    }
  }

  // ---- 6. Interpolate any unmatched words using nearest matched neighbors ----
  const interpolated = matched.map((m) => m); // shallow copy to fill in

  const fillGap = (startIdx, endIdx, before, after) => {
    // before/after are {start,end} or undefined (sequence boundary)
    const beforeTime = before ? before.end : (after ? after.start : 0);
    const afterTime = after ? after.start : (before ? before.end : beforeTime);
    const span = endIdx - startIdx + 1;
    for (let k = 0; k < span; k++) {
      const t = span === 1 ? beforeTime : beforeTime + ((afterTime - beforeTime) * (k + 1)) / (span + 1);
      interpolated[startIdx + k] = { start: t, end: t, interpolated: true };
    }
  };

  {
    let gapStart = -1;
    for (let k = 0; k <= n; k++) {
      const isGap = k < n && interpolated[k] === null;
      if (isGap && gapStart === -1) gapStart = k;
      if (!isGap && gapStart !== -1) {
        const before = gapStart > 0 ? interpolated[gapStart - 1] : undefined;
        const after = k < n ? interpolated[k] : undefined;
        fillGap(gapStart, k - 1, before, after);
        gapStart = -1;
      }
    }
  }

  // ---- 7. Build per-paragraph output ----
  const results = paragraphs.map((p) => ({ text: p.text, verseNumber: p.verseNumber, start: 0, end: 0, boundaries: [] }));

  for (let pIdx = 0; pIdx < paragraphs.length; pIdx++) {
    const wordsInPara = paraWords
      .map((w, gIdx) => ({ ...w, globalIdx: gIdx }))
      .filter((w) => w.paragraphIndex === pIdx);

    if (wordsInPara.length === 0) {
      results[pIdx].start = pIdx > 0 ? results[pIdx - 1].end : 0;
      results[pIdx].end = results[pIdx].start;
      continue;
    }

    const times = wordsInPara.map((w) => interpolated[w.globalIdx]);
    results[pIdx].start = times[0].start;
    results[pIdx].end = times[times.length - 1].end;

    // boundaries: transition time between each consecutive word pair within this paragraph
    for (let k = 0; k < times.length - 1; k++) {
      const gapEnd = times[k].end;
      const gapStart = times[k + 1].start;
      results[pIdx].boundaries.push((gapEnd + gapStart) / 2);
    }
  }

  // ---- 8. Snap each paragraph's end to the next paragraph's start for continuous, gap-free lookup ----
  for (let pIdx = 0; pIdx < results.length - 1; pIdx++) {
    results[pIdx].end = results[pIdx + 1].start;
  }

  return results;
}